import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"13、【同人】 离下乾上","description":"周易集注 - 13、【同人】 离下乾上","frontmatter":{"title":"13、【同人】 离下乾上","description":"周易集注 - 13、【同人】 离下乾上"},"headers":[],"relativePath":"zh/classics/jizhu/017.md","filePath":"zh/classics/jizhu/017.md"}'),h={name:"zh/classics/jizhu/017.md"};function t(l,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_13、【同人】-离下乾上" tabindex="-1">13、【同人】 离下乾上 <a class="header-anchor" href="#_13、【同人】-离下乾上" aria-label="Permalink to “13、【同人】 离下乾上”">​</a></h1><p>同人者，与人同也。天在上，火性炎上，上与天同，同人之象也。二五皆居正位，以中正相同，同人之义也。又一阴而五阳，欲同之，亦同人也。《序卦》“物不可以终否，故受之以同人”，所以次否。</p><p>《彖》曰：同人，柔得位得中而应乎干，曰同人。同人曰：同人于野，亨，利涉大川，乾行也。文明以健，中正而应，君子正也。唯君子为能通天下之志。</p><p>以卦综释卦名，以卦德卦体释卦辞。同人大有二卦同体，文王综为一卦，故《杂卦》曰“大有众也，同人亲也”。柔得位得中者，八卦正位，离在二。今大有上卦之离，来居同人之下卦，则不惟得八卦之正位，又得其中，而应乾九五之中正者也。下与上相同，故名同人。卦辞同人于野者，六二应乎干，干在外卦，乃野外也，故曰于野。乾行，指利涉大川一句。盖乾刚健中正，且居九五之位，有德有位，故可以济险难。同人于野，虽六二得位得中所能同，至于济险难则非六二阴柔所能也，故曰乾行。犹言干之能事也。本卦错师，有震木坎水象，所以利涉大川。曰乾行者，不言象而言理也。内文明则能察于理，外刚健则能勇于义，中正则内无人欲之私，应干则外合天德之公。文明以健，以德言。中正而应，以爻言。此四者，皆君子之正道也。惟君子能通天下之志者，君子即正也。同人于野者六二也，利涉大川者干也，君子贞则緫六二九五言之。</p><p>六二应乎九五之干，固名同人矣。然同人卦辞乃曰“同人于野亨，利涉大川”，何也?盖六二应干固亨矣，至于利涉大川，非六二也，乃干也。曰“利君子贞”者何也?盖内外卦绵君子之正，所以利君子正，天下之理正而已矣。人同此心，同此理，亿兆之众志虽不同，惟此正理，方可通之，方可大同人心。若私邪不正，安能有于野之亨，而利涉哉。此所以利君子贞也。</p><h3 id="《象》曰-天与火同人-君子以类族辨物。" tabindex="-1">《象》曰：天与火同人，君子以类族辨物。 <a class="header-anchor" href="#《象》曰-天与火同人-君子以类族辨物。" aria-label="Permalink to “《象》曰：天与火同人，君子以类族辨物。”">​</a></h3><p>类族者，于其族而类之，如父母之类皆三年之丧，兄弟之类皆期年之丧是也。辨物者，于其物而辨之，如如三年之丧其服之麻极粗，期年之丧稍粗，以下渐细是也。是则同轨同伦，道德可一，风俗可同，亦如天与火不同而同也。凡大象皆有功夫，故曰君子以，以者用也。若以类族为人，士为士族，农为农族，以辨物为物，蜾为蜾物，羽为羽物，则君子以三字无安顿而托空矣。</p><p>初九，同人于门，无咎。</p><p>变艮为门，门之象也。于门者，谓于门外也。门外虽非野之可比，然亦在外，则所同者广而无私昵矣。</p><p>初九以刚正居下，当同人之初，而上无系应，故有同人于门之象。占者如是，则无咎也。</p><h3 id="《象》曰-出门同人-又谁咎也。" tabindex="-1">《象》曰：出门同人，又谁咎也。 <a class="header-anchor" href="#《象》曰-出门同人-又谁咎也。" aria-label="Permalink to “《象》曰：出门同人，又谁咎也。”">​</a></h3><p>所同者广而无偏党之私，又谁有咎我者。</p><p>六二，同人于宗，吝。</p><p>凡离变干而应乎阳者，皆谓之宗。盖干乃六十四卦阳爻之祖，有祖则有宗，故所应者为宗。若原是乾卦，则本然之祖，见阳不言宗。惟新变之干，则新成祖矣，所以见阳言宗也。故睽卦六五，亦曰宗。统论一卦，则二五中正相应，所以亨。若论二之一爻，则是阴欲同乎阳矣，所以可羞。如履卦彖辞，履帝位而不疚，至本爻则贞厉，皆此意。</p><p>同人贵无私，六二中正，所应之五，亦中正，然卦取同人，阴欲同乎阳，臣妾顺从之道也，溺于私而非公矣，岂不羞。故其象占如此。</p><h3 id="《象》曰-同人于宗-吝道也。" tabindex="-1">《象》曰：同人于宗，吝道也。 <a class="header-anchor" href="#《象》曰-同人于宗-吝道也。" aria-label="Permalink to “《象》曰：同人于宗，吝道也。”">​</a></h3><p>阴欲同乎阳，所私在一人，可羞之道也。</p><p>九三，伏戎于莽，升其高陵，三岁不兴。</p><p>离错坎为隐伏，伏之象也。中爻巽为入，亦伏之象也。离为戈兵，戎之象也。莽，草也，中爻巽为阴，木草之象也。中爻巽为股，三变为震足，股足齐动，升之象也。巽为高，高之象也。三变，中爻艮，陵之象也。离居三，三之象也。兴，发也。伏戎于莽者，俟其五之兵也。升其高陵者，窥其二之动也。对五而言，三在五之下，故曰伏;对二而言，三在二之上，故曰升。</p><p>九三刚而不中，上无应与，欲同于二，而二乃五之正应，恐九五之见攻，故伏兵于草，升高盼望，将以敌五而攘二。然以理言，二非正应，理不直;以势言，五居尊位，势不敌。故至三年之久，而终不发。其象如此，以其未发，故占者不言凶。</p><h3 id="《象》曰-伏戎于莽-敌刚也。三岁不兴-安行也。" tabindex="-1">《象》曰：伏戎于莽，敌刚也。三岁不兴，安行也。 <a class="header-anchor" href="#《象》曰-伏戎于莽-敌刚也。三岁不兴-安行也。" aria-label="Permalink to “《象》曰：伏戎于莽，敌刚也。三岁不兴，安行也。”">​</a></h3><p>所敌者既刚且正，故伏藏。三岁不兴者，以理与势俱屈，安敢行哉，故不能行。盖行者，则兴动而行也。安者，安于理势而不兴也，故曰安行。安行即四困则之意。</p><p>九四，乘其墉，弗克攻，吉。</p><p>墉，墙也。离中虚外围，墉之象也。解卦上六变离，亦曰墉，泰卦上六变艮，大象离曰城，皆以中空外围也。此则九三为六二之墉，九四在上，故曰乘。二四皆争夺，非同人矣，故不言同人。三恶五之亲二，故有犯上之心，四恶二之比三，故有陵下之志。六二，其三国之荆州乎。</p><p>四不中正，当同人之时无应与，亦欲同于六二，三为二之墉，故有乘墉攻二之象。然以刚居柔，故又有自反而弗克攻之象，能如是则能改过矣，故占者吉。</p><h3 id="《象》曰-乘其墉-义弗克也。其吉-则困而反则也。" tabindex="-1">《象》曰：乘其墉，义弗克也。其吉，则困而反则也。 <a class="header-anchor" href="#《象》曰-乘其墉-义弗克也。其吉-则困而反则也。" aria-label="Permalink to “《象》曰：乘其墉，义弗克也。其吉，则困而反则也。”">​</a></h3><p>义者理也，则者理之法则也。义理不可移易，故谓之则。当同而同者，理也，亦法则也。不当同而不同者，理也，亦法则也。困者困穷也，即困而右之之困也。四刚强，本欲攻二，然其志柔，又思二乃五之正应，义不可攻，欲攻不可攻，二者交战往来于此心，故曰困。困之一字，非孔子不能说出，九四之心也。若生而知之，知其不可攻。学而知之，知其不可攻，则此心不困矣。言乘其墉矣，岂其力之不足哉，特以义不可同，故弗克攻耳。其吉者，则因困于心而反于义理之法则也。因困则改过矣，故吉。义弗克，正理也。困而反则，九四功夫也。</p><p>九五，同人先号咷而后笑，大师克相遇。(号平声)</p><p>火无定体，曰鼓缶而歌，而嗟出涕沱，若中孚象离曰或泣或歌，九五又变离，故有此象。先号咷后笑者，本卦六爻未变，离错坎为加忧，九五隔于三四，故忧而号咷。及九五变，则中爻为兑悦，故后笑。旅先笑后号咷者，本卦未变，中爻兑悦，故先笑，及上九变，则悦体震动，成小过，灾眚之凶矣，故后号咷。必用大师者，三伏莽，四乘墉，非大师岂能克。此爻变离，中爻错震，戈兵震动，师之象也。九五阳刚之君，阳大阴小，大师之象也。且本卦错师，亦有师象。</p><p>九五、六二，以刚柔中正相应，本同心者也，但为三四强暴所隔，虽同矣，不得遽与之同，故有未同时不胜号咷，既同后不胜喜笑之象。故圣人教占者曰，君臣大分也，以臣隔君，大逆也。当此之时，为君者宜兴大师，克乎强暴后，方遇乎正应而后可。若号咷，则失其君之威矣。故教占者，占中之象又如此。</p><h3 id="《象》曰-同人之先-以中直也。大师相遇-言相克也。" tabindex="-1">《象》曰：同人之先，以中直也。大师相遇，言相克也。 <a class="header-anchor" href="#《象》曰-同人之先-以中直也。大师相遇-言相克也。" aria-label="Permalink to “《象》曰：同人之先，以中直也。大师相遇，言相克也。”">​</a></h3><p>先者，先号咷也。以者因也。中直与困卦九五中直同，即中正也。言九五所以先号咷者，以中正相应，必欲同之也。相克者九五克三四也。</p><p>上九，同人于郊，无悔。</p><p>干为郊，郊之象也，详见需卦。国外曰郊，郊外曰野，皆旷远之地。但同人于野以卦之全体而言，言大同则能亨也。故于野取旷远大同之象，此爻则取旷远无所与同之象，各有所取也。</p><p>上九居同人之终，又无应与，则无人可同矣，故有同人于郊之象。既无所同，则亦无所悔，故其占如此。</p><h3 id="《象》曰-同人于郊-志未得也。" tabindex="-1">《象》曰：同人于郊，志未得也。 <a class="header-anchor" href="#《象》曰-同人于郊-志未得也。" aria-label="Permalink to “《象》曰：同人于郊，志未得也。”">​</a></h3><p>无人可同则不能通天下之志矣，志未得，正与通天下之志相反。</p>',37)])])}const f=e(h,[["render",t]]);export{_ as __pageData,f as default};
